import {readFile} from 'node:fs/promises';
import {resolve, dirname} from 'node:path';
import {parseWorkerModule, rewriteModule} from './worker-module.js';

function resolveExport(module, name) {
  const exported = module.exports.get(name);
  if (!exported) throw new Error(`Unknown or ambiguous worker export ${name} in ${module.path}`);
  return {expression: `__module${module.id}[${JSON.stringify(name)}]`, origin: exported.origin};
}

function dependencyEdits(dependencies, imported, exported) {
  const edits = [], stars = new Map(), ambiguous = new Set();
  for (const {statement, module} of dependencies) {
    let replacement = '';
    if (statement.kind === 'namespace') {
      imported.set(statement.alias, {expression: `__module${module.id}`, origin: `namespace\0${module.path}`});
      replacement = `const ${statement.alias} = __module${module.id};`;
    }
    else if (statement.kind === 'named') {
      const names = [];
      for (const binding of statement.bindings) {
        imported.set(binding.alias, resolveExport(module, binding.name));
        names.push(`${binding.name}:${binding.alias}`);
      }
      replacement = `const {${names.join(',')}} = __module${module.id};`;
    } else if (statement.kind === 'reexport') {
      for (const binding of statement.bindings) {
        if (exported.has(binding.alias)) throw new Error(`Duplicate worker export ${binding.alias}`);
        exported.set(binding.alias, resolveExport(module, binding.name));
      }
    } else {
      for (const name of module.exports.keys()) {
        if (name === 'default') continue;
        const value = resolveExport(module, name), previous = stars.get(name);
        if (previous && previous.origin !== value.origin) ambiguous.add(name);
        else stars.set(name, value);
      }
    }
    edits.push({...statement, replacement});
  }
  for (const [name, value] of stars) if (!ambiguous.has(name) && !exported.has(name)) exported.set(name, value);
  return edits;
}

function compileModule(path, parsed, dependencies, id) {
  const imported = new Map(), exported = new Map();
  const edits = dependencyEdits(dependencies, imported, exported);
  const localNames = new Set();
  for (const binding of parsed.exports) {
    if (localNames.has(binding.alias)) throw new Error(`Duplicate worker export ${binding.alias}`);
    localNames.add(binding.alias);
    exported.set(binding.alias, imported.get(binding.name) ?? {expression: binding.name, origin: `${path}\0${binding.name}`});
  }
  const source = rewriteModule(parsed.source, [...parsed.edits, ...edits]);
  const getters = [...exported].map(([name, value]) => `[${JSON.stringify(name)}]:()=>${value.expression}`).join(',');
  return {id, path, exports: exported, source: `const __module${id} = (() => {\n${source}\nreturn __workerNamespace({${getters}});\n})();`};
}

const namespaceFactory = `function __workerNamespace(bindings) {
  const namespace = Object.create(null);
  for (const name of Object.keys(bindings).sort()) {
    Object.defineProperty(namespace, name, {enumerable: true, get: bindings[name]});
  }
  Object.defineProperty(namespace, Symbol.toStringTag, {value: 'Module'});
  return Object.freeze(namespace);
}`;

/** Bundle the acyclic static import graph; each module executes once and namespace imports share a read-only export view. */
export async function bundleWorker(entry) {
  const modules = [], complete = new Map(), visiting = new Set();
  async function visit(input) {
    const path = resolve(input);
    if (visiting.has(path)) throw new Error(`Worker module cycle: ${path}`);
    if (complete.has(path)) return complete.get(path);
    visiting.add(path);
    try {
      const source = await readFile(path, 'utf8');
      const parsed = parseWorkerModule(source, path), dependencies = [];
      for (const statement of parsed.dependencies) {
        if (!statement.specifier.startsWith('.')) throw new Error(`Unresolved worker dependency ${statement.specifier}`);
        const module = await visit(resolve(dirname(path), statement.specifier));
        dependencies.push({statement, module});
      }
      const module = compileModule(path, parsed, dependencies, modules.length);
      modules.push(module.source);
      complete.set(path, module);
      return module;
    } finally { visiting.delete(path); }
  }
  await visit(entry);
  return '/* SharpForge static worker bundle. Generated by scripts/bundle-worker.js. */\n'
    + `'use strict';\n(() => {\n${namespaceFactory}\n${modules.join('\n')}\n})();\n`;
}
